package com.mealflex.risk.entity; import com.mealflex.common.entity.BaseEntity; import com.mealflex.user.entity.User; import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Entity @Table(name="risk_cases") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class RiskCase extends BaseEntity { @Column(name="risk_type",nullable=false) private String riskType; @Column(nullable=false) private String severity; @Column(name="reference_type",nullable=false) private String referenceType; @Column(name="reference_id",nullable=false) private Long referenceId; @Column(nullable=false) private String summary; @Column(nullable=false) private String status; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assigned_admin_id") private User assignedAdmin; @Column(name="resolution_note",length=1000) private String resolutionNote; private Instant resolvedAt; }
